urlset:
{% for sitemap_entry in entries %}

    {{ sitemap_entry.permalink | safe }}
    {{ now() | date(format="%Y-%m-%d") }}
    {% if sitemap_entry.permalink is ending_with("/") or sitemap_entry.permalink is ending_with("/en/") %}weekly{% else %}monthly{% endif %}
    {% if sitemap_entry.permalink is ending_with("teina.es/") or sitemap_entry.permalink is ending_with("/en/") %}1.0{% elif "musica" in sitemap_entry.permalink or "banda" in sitemap_entry.permalink or "contacto" in sitemap_entry.permalink or "media" in sitemap_entry.permalink %}0.8{% else %}0.5{% endif %}

{% endfor %}
